import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';

export const findWalletItemOrigin = (
  walletList: UserWalletResponse[] | null | undefined,
  key: keyof UserWalletResponse,
  value: string | number | null | undefined,
): UserWalletResponse => {
  if (!walletList) return {} as UserWalletResponse;
  return walletList.find((item) => item[key] === value) ?? ({} as UserWalletResponse);
};

export const findTokenItemByAliasNm = (
  walletList: UserWalletResponse[] | null | undefined,
  aliasNm: string,
): UserWalletResponse => {
  if (!walletList) return {} as UserWalletResponse;
  return findWalletItemOrigin(walletList, 'aliasNm', aliasNm);
};

//지갑 아이템에서 특정 키 값 찾기
export const findWalletItem = <SelectedInfo extends keyof UserWalletResponse>(
  selectedWallet: UserWalletResponse | null | undefined,
  keys: SelectedInfo[],
): Pick<UserWalletResponse, SelectedInfo> => {
  if (!selectedWallet) return {} as Pick<UserWalletResponse, SelectedInfo>;

  return keys.reduce(
    (acc, key) => {
      acc[key] = selectedWallet[key];
      return acc;
    },
    {} as Pick<UserWalletResponse, SelectedInfo>,
  );
};

export const findWalletItemByKey = <SelectedInfo extends keyof UserWalletResponse>(
  selectedWallet: UserWalletResponse | null | undefined,
  key: SelectedInfo[],
): Pick<UserWalletResponse, SelectedInfo> => {
  if (!selectedWallet) return {} as Pick<UserWalletResponse, SelectedInfo>;
  return findWalletItem(selectedWallet, key);
};
